<?php
require_once __DIR__ . '/../config/auth.php';
requireRole('student');
$pageTitle='Student Dashboard';$base='/ams';$user=currentUser();
$stmt=db()->prepare("SELECT COUNT(*) total,SUM(status='Present') present,SUM(status='Late') late,SUM(status='Absent') absent FROM attendance WHERE student_id=?");$stmt->execute([$user['id']]);$s=$stmt->fetch();$total=(int)$s['total'];$present=(int)$s['present'];$late=(int)$s['late'];$absent=(int)$s['absent'];$rate=$total?round($present/$total*100):0;
$recent=db()->prepare('SELECT attendance_date,status,time_in,remarks FROM attendance WHERE student_id=? ORDER BY attendance_date DESC LIMIT 5');$recent->execute([$user['id']]);$rows=$recent->fetchAll();
require __DIR__.'/../includes/header.php'; ?>
<section class="hero-banner"><div><span class="eyebrow">STUDENT PORTAL</span><h2>Welcome, <?= e(explode(' ',$user['full_name'])[0]) ?>.</h2><p>Keep an eye on your attendance and personal information.</p></div><a class="btn btn-light" href="profile.php">My profile →</a></section>
<section class="stats-grid"><div class="stat-card"><span>Attendance Rate</span><strong><?= $rate ?>%</strong><small>Based on your records</small></div><div class="stat-card"><span>Present</span><strong><?= $present ?></strong><small>Days present</small></div><div class="stat-card"><span>Late</span><strong><?= $late ?></strong><small>Days late</small></div><div class="stat-card"><span>Absent</span><strong><?= $absent ?></strong><small>Days absent</small></div></section>
<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Recent attendance</h2><p>Your latest attendance activity.</p></div><a class="btn btn-outline btn-sm" href="attendance.php">View all</a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Time in</th><th>Status</th><th>Remarks</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['attendance_date']) ?></td><td><?= e($r['time_in']?:'—') ?></td><td><span class="badge <?= strtolower($r['status']) ?>"><?= e($r['status']) ?></span></td><td><?= e($r['remarks']?:'—') ?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="4" class="empty">No attendance records yet.</td></tr><?php endif; ?></tbody></table></div></section><section class="panel profile-mini"><span class="eyebrow">MY PROFILE</span><h2><?= e($user['full_name']) ?></h2><p><?= e($user['student_no']) ?> · <?= e($user['course']) ?></p><a href="profile.php" class="quick-action">Open profile <span>→</span></a><a href="attendance.php" class="quick-action">Attendance history <span>→</span></a></section></div>
<?php require __DIR__.'/../includes/footer.php'; ?>
